// Normalise GHL appointments, drop what we can't use, geocode new addresses.
// Nominatim usage policy: max 1 request/second, identifying User-Agent.

const GEOCODE_DELAY_MS = 1100;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const cfg = $('Config').first().json;
const events = $input.first().json.events || [];

// Installer lookup: GHL user id -> Supabase installer id
const installers = await this.helpers.httpRequest({
  method: 'GET',
  url: `${cfg.supabaseUrl}/rest/v1/installers?select=id,ghl_user_id&active=eq.true`,
  headers: { apikey: cfg.supabaseServiceKey, Authorization: `Bearer ${cfg.supabaseServiceKey}` },
  json: true,
});
const byGhlUser = Object.fromEntries(installers.filter(i => i.ghl_user_id).map(i => [i.ghl_user_id, i.id]));

// Appointments we already have coordinates for — don't re-geocode.
const known = await this.helpers.httpRequest({
  method: 'GET',
  url: `${cfg.supabaseUrl}/rest/v1/jobs?select=ghl_appointment_id,address,lat,lng&lat=not.is.null`,
  headers: { apikey: cfg.supabaseServiceKey, Authorization: `Bearer ${cfg.supabaseServiceKey}` },
  json: true,
});
const cachedByAddress = Object.fromEntries(known.filter(j => j.address).map(j => [j.address.trim().toLowerCase(), j]));

const out = [];
const skipped = [];

for (const ev of events) {
  const status = (ev.appointmentStatus || '').toLowerCase();
  if (status === 'cancelled') continue;

  const installerId = byGhlUser[ev.assignedUserId];
  if (!installerId) {
    // Unassigned jobs cannot appear in anyone's list. Surface, don't silently drop.
    skipped.push({ id: ev.id, reason: 'no matching installer for assignedUserId ' + ev.assignedUserId });
    continue;
  }

  const address = (ev.address || ev.meetingLocation || '').trim();
  let lat = null, lng = null;

  if (address) {
    const cached = cachedByAddress[address.toLowerCase()];
    if (cached) {
      lat = cached.lat; lng = cached.lng;
    } else {
      await sleep(GEOCODE_DELAY_MS);
      try {
        const res = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://nominatim.openstreetmap.org/search',
          qs: { q: address, format: 'json', limit: 1, countrycodes: 'au' },
          headers: { 'User-Agent': 'AtticPlus-SiteCheckin/1.0 (info@adalytics.com.au)' },
          json: true,
        });
        if (res && res[0]) { lat = parseFloat(res[0].lat); lng = parseFloat(res[0].lon); }
      } catch (e) {
        skipped.push({ id: ev.id, reason: 'geocode failed: ' + e.message });
      }
    }
  } else {
    skipped.push({ id: ev.id, reason: 'no address on appointment — distance cannot be measured' });
  }

  out.push({
    json: {
      source: 'ghl_calendar',
      ghl_appointment_id: ev.id,
      ghl_contact_id: ev.contactId || null,
      customer_name: ev.title || null,
      address: address || null,
      lat, lng,
      geocoded_at: lat ? new Date().toISOString() : null,
      scheduled_start: ev.startTime,
      scheduled_end: ev.endTime,
      assigned_installer_id: installerId,
      status: 'scheduled',
      synced_at: new Date().toISOString(),
    },
  });
}

if (skipped.length) console.log('SKIPPED APPOINTMENTS:', JSON.stringify(skipped, null, 2));
return out;
